const G=(labels,edges)=>({nodes:labels.map((label,id)=>({id,label})),edges:edges.map((e,id)=>({id,a:e[0],b:e[1],order:e[2]||1,stereo:e[3]||''}))});
const sgLine=(x1,y1,x2,y2,order=1)=>{const dx=x2-x1,dy=y2-y1,len=Math.hypot(dx,dy)||1,nx=-dy/len*3.3,ny=dx/len*3.3,ks=order===1?[0]:order===2?[-1,1]:[-1.6,0,1.6];return ks.map(k=>`<line x1="${x1+nx*k}" y1="${y1+ny*k}" x2="${x2+nx*k}" y2="${y2+ny*k}"/>`).join('')};
const sgText=(x,y,t,cls='atom')=>`<text x="${x}" y="${y}" class="${cls}" text-anchor="middle">${t}</text>`;
const sgArrow=(x1,x2,y,label='')=>`${label?sgText((x1+x2)/2,y-15,label,'reagent'):''}<line x1="${x1}" y1="${y}" x2="${x2}" y2="${y}" class="arrow"/><path d="M${x2-11} ${y-7}L${x2} ${y}L${x2-11} ${y+7}" class="arrow"/>`;
const sgWrap=(body,label)=>`<div class="prompt-structure"><div class="eyebrow">Given structures</div><svg viewBox="0 0 680 150" role="img" aria-label="${label}"><g class="skeletal">${body}</g></svg></div>`;
function reactantScheme(id){
  const diene=sgLine(42,88,82,62,2)+sgLine(82,62,122,88,1)+sgLine(122,88,162,62,2);
  const triene=diene+sgLine(162,62,202,88,1)+sgLine(202,88,242,62,2);
  const ethylene=sgLine(238,78,302,78,2),acetylene=sgLine(238,78,302,78,3);
  const cyclo=sgLine(55,55,95,34,2)+sgLine(95,34,135,55)+sgLine(135,55,135,100)+sgLine(135,100,95,122)+sgLine(95,122,55,100)+sgLine(55,100,55,55);
  const benz=sgLine(55,55,95,34,2)+sgLine(95,34,135,55)+sgLine(135,55,135,100,2)+sgLine(135,100,95,122)+sgLine(95,122,55,100,2)+sgLine(55,100,55,55);
  const acetone=sgLine(55,102,100,78)+sgLine(100,78,145,102)+sgLine(100,78,100,30,2)+sgText(100,22,'O');
  const propanal=sgLine(220,102,260,78)+sgLine(260,78,300,102)+sgLine(300,102,300,50,2)+sgText(300,42,'O')+sgText(325,112,'H','small-atom');
  const cyclohexanone=sgLine(55,55,95,34)+sgLine(95,34,135,55)+sgLine(135,55,135,100)+sgLine(135,100,95,122)+sgLine(95,122,55,100)+sgLine(55,100,55,55)+sgLine(95,34,95,3,2)+sgText(95,2,'O');
  const question=sgText(615,84,'?','question-mark');
  if(['draw-004','draw-005','draw-019'].includes(id))return sgWrap(diene+sgText(210,82,'+','symbol')+sgText(265,82,'H–Br','formula-label')+sgArrow(340,550,78,'')+question,'1,3-butadiene plus hydrogen bromide yields an unknown product');
  if(['draw-020','draw-021'].includes(id))return sgWrap(diene+sgText(210,82,'+','symbol')+sgText(265,82,'H–Cl','formula-label')+sgArrow(340,550,78,'')+question,'1,3-butadiene plus hydrogen chloride yields an unknown product');
  if(id==='draw-006')return sgWrap(triene+sgText(285,82,'+','symbol')+sgText(340,82,'H–Br','formula-label')+sgArrow(410,550,78,'')+question,'1,3,5-hexatriene plus hydrogen bromide yields an unknown product');
  if(id==='draw-007')return sgWrap(diene+sgText(200,82,'+','symbol')+ethylene+sgArrow(355,550,78,'Δ')+question,'1,3-butadiene plus ethylene under heat yields an unknown product');
  if(id==='draw-008')return sgWrap(diene+sgText(200,82,'+','symbol')+acetylene+sgArrow(355,550,78,'Δ')+question,'1,3-butadiene plus acetylene under heat yields an unknown product');
  if(id==='draw-009')return sgWrap(cyclo+sgArrow(205,535,78,'1. OsO₄, NMO   2. H₂O')+question,'cyclohexene treated with osmium tetroxide, NMO and water yields an unknown product');
  if(id==='draw-010')return sgWrap(sgText(55,84,'?','question-mark')+sgArrow(100,255,78,'1. O₃   2. DMS')+`<g transform="translate(270 0)">${acetone}</g>`+sgText(455,82,'+','symbol')+`<g transform="translate(270 0)">${propanal}</g>`,'unknown alkene gives acetone and propanal under reductive ozonolysis');
  if(id==='draw-011')return sgWrap(cyclo+sgArrow(205,535,78,'1. O₃   2. DMS')+question,'cyclohexene under reductive ozonolysis yields an unknown product');
  if(id==='draw-013')return sgWrap(acetone+sgText(190,82,'+','symbol')+sgText(295,82,'Ph₃P=CH₂','formula-label')+sgArrow(400,550,78,'')+question,'acetone plus methylene triphenylphosphorane yields an unknown alkene');
  if(id==='draw-014')return sgWrap(cyclohexanone+sgText(190,82,'+','symbol')+sgText(305,82,'Ph₃P=CH₂','formula-label')+sgArrow(415,550,78,'')+question,'cyclohexanone plus methylene triphenylphosphorane yields an unknown alkene');
  if(id==='draw-016')return sgWrap(benz+sgText(180,82,'+','symbol')+sgText(245,82,'Br₂','formula-label')+sgArrow(320,550,78,'FeBr₃')+question,'benzene plus bromine with ferric bromide yields an unknown product');
  if(id==='draw-022')return sgWrap(diene+sgText(200,82,'+','symbol')+sgLine(238,92,270,62,2)+sgLine(270,62,305,92)+sgArrow(355,550,78,'Δ')+question,'1,3-butadiene plus propene under heat yields an unknown product');
  if(['draw-023','draw-024'].includes(id)){const alkene=sgLine(238,78,302,78,2)+sgLine(238,78,218,id==='draw-023'?48:108)+sgLine(302,78,322,48);return sgWrap(diene+sgText(200,82,'+')+alkene+sgArrow(360,550,78,'Δ')+question,`1,3-butadiene plus ${id==='draw-023'?'cis':'trans'}-2-butene under heat yields an unknown product`)}
  if(id==='draw-025'){const isoprene=diene+sgLine(82,62,82,24);return sgWrap(isoprene+sgText(210,82,'+')+ethylene+sgArrow(355,550,78,'Δ')+question,'isoprene plus ethylene under heat yields an unknown product')}
  if(id==='draw-026'){const c5=sgLine(55,62,95,36,2)+sgLine(95,36,136,66)+sgLine(136,66,120,112)+sgLine(120,112,68,112)+sgLine(68,112,55,62);return sgWrap(c5+sgArrow(205,535,78,'1. OsO₄, NMO   2. H₂O')+question,'cyclopentene treated with osmium tetroxide, NMO and water yields an unknown product')}
  if(id==='draw-027')return sgWrap(sgLine(50,78,105,78,2)+sgLine(105,78,145,45)+sgLine(105,78,145,111)+sgArrow(205,535,78,'1. OsO₄, NMO   2. H₂O')+question,'2-methylpropene treated with osmium tetroxide, NMO and water yields an unknown product');
  if(id==='draw-028')return sgWrap(sgLine(50,78,105,78,2)+sgLine(105,78,145,45)+sgLine(105,78,145,111)+sgArrow(205,535,78,'1. O₃   2. DMS')+question,'2-methylpropene under reductive ozonolysis yields two unknown products');
  if(id==='draw-029')return sgWrap(sgLine(40,82,85,58)+sgLine(85,58,130,82,2)+sgLine(130,82,175,55)+sgLine(175,55,215,82)+sgLine(130,82,145,125)+sgArrow(255,535,78,'1. O₃   2. DMS')+question,'3-methyl-2-pentene under reductive ozonolysis yields two unknown products');
  if(id==='draw-030')return sgWrap(sgText(55,84,'?','question-mark')+sgArrow(100,255,78,'1. O₃   2. DMS')+`<g transform="translate(270 0)">${acetone}</g>`+sgText(455,82,'+')+sgLine(500,78,500,30,2)+sgText(500,22,'O')+sgText(525,84,'H₂C','formula-label'),'an unknown alkene gives acetone and formaldehyde under reductive ozonolysis');
  if(id==='draw-031'){const c5=sgLine(55,62,95,36,2)+sgLine(95,36,136,66)+sgLine(136,66,120,112)+sgLine(120,112,68,112)+sgLine(68,112,55,62);return sgWrap(c5+sgArrow(205,535,78,'1. O₃   2. DMS')+question,'cyclopentene under reductive ozonolysis yields an unknown product')}
  if(id==='draw-032')return sgWrap(benz+sgLine(135,100,175,112)+sgLine(175,112,175,58,2)+sgText(175,50,'O')+sgText(198,118,'H','small-atom')+sgText(235,82,'+')+sgText(330,82,'Ph₃P=CH₂','formula-label')+sgArrow(420,550,78,'')+question,'benzaldehyde plus methylene triphenylphosphorane yields an unknown alkene');
  if(id==='draw-033'){const c5o=sgLine(55,62,95,36)+sgLine(95,36,136,66)+sgLine(136,66,120,112)+sgLine(120,112,68,112)+sgLine(68,112,55,62)+sgLine(95,36,95,5,2)+sgText(95,3,'O');return sgWrap(c5o+sgText(175,82,'+')+sgText(280,82,'Ph₃P=CH₂','formula-label')+sgArrow(380,535,78,'')+question,'cyclopentanone plus methylene triphenylphosphorane yields an unknown alkene')}
  if(id==='draw-034')return sgWrap(sgText(85,82,'CH₃–CH=O','formula-label')+sgText(180,82,'+')+sgText(295,82,'Ph₃P=CH–CH₃','formula-label')+sgArrow(420,550,78,'')+question,'ethanal plus ethylidene triphenylphosphorane yields an unknown alkene');
  if(id==='draw-035')return sgWrap(acetone+sgText(190,82,'+')+sgText(315,82,'Ph₃P=CH–CH₃','formula-label')+sgArrow(445,560,78,'')+question,'acetone plus ethylidene triphenylphosphorane yields an unknown alkene');
  if(id==='draw-036'){const c5o=sgLine(55,62,95,36)+sgLine(95,36,136,66)+sgLine(136,66,120,112)+sgLine(120,112,68,112)+sgLine(68,112,55,62)+sgLine(95,36,95,5,2)+sgText(95,3,'O');return sgWrap(c5o+sgArrow(190,555,78,'1. Ph₃P=CH₂   2. OsO₄, NMO; H₂O')+question,'cyclopentanone treated first with a methylene Wittig reagent and then osmium tetroxide yields an unknown product')}
  if(id==='draw-040')return sgWrap(benz+sgText(180,82,'+')+sgText(245,82,'Cl₂','formula-label')+sgArrow(320,550,78,'FeCl₃')+question,'benzene plus chlorine with ferric chloride yields an unknown product');
  return '';
}
var DRAW_BANK=[
  {id:'draw-001',topic:'Foundations',prompt:'Draw propene, CH₃CH=CH₂, as a line structure.',hint:'Three carbons; the double bond is terminal.',answer:'CH₃–CH=CH₂',target:G(['C','C','C'],[[0,1,1],[1,2,2]]),explain:'Propene has a three-carbon chain and one terminal C=C. The unlabeled end and vertex are carbon atoms.'},
  {id:'draw-002',topic:'Conjugation',prompt:'Draw 1,3-butadiene.',hint:'Four carbons with alternating double and single bonds.',answer:'CH₂=CH–CH=CH₂',target:G(['C','C','C','C'],[[0,1,2],[1,2,1],[2,3,2]]),explain:'A conjugated diene has C=C–C=C: two π bonds separated by one single bond.'},
  {id:'draw-003',topic:'Conjugation',prompt:'Draw 1,3,5-hexatriene.',hint:'Six carbons. Start at one end and alternate bond orders.',answer:'CH₂=CH–CH=CH–CH=CH₂',target:G(['C','C','C','C','C','C'],[[0,1,2],[1,2,1],[2,3,2],[3,4,1],[4,5,2]]),explain:'The three π bonds begin at C1, C3 and C5, producing a six-center conjugated system.'},
  {id:'draw-004',topic:'Conjugated addition',prompt:'Draw the 1,2-addition product from HBr addition to 1,3-butadiene after H adds to C1.',hint:'Br is on C2; the C3=C4 bond remains.',answer:'CH₃–CH(Br)–CH=CH₂',target:G(['C','C','C','C','Br'],[[0,1,1],[1,2,1],[2,3,2],[1,4,1]]),explain:'H adds at C1 and Br captures C2. The untouched π bond remains between C3 and C4.'},
  {id:'draw-005',topic:'Conjugated addition',prompt:'Draw the 1,4-addition product from HBr addition to 1,3-butadiene after H adds to C1.',hint:'Br is on C4; the new double bond is C2=C3.',answer:'CH₃–CH=CH–CH₂Br',target:G(['C','C','C','C','Br'],[[0,1,1],[1,2,2],[2,3,1],[3,4,1]]),explain:'Resonance places positive charge at C4, where Br attacks. The remaining double bond is between the inner carbons.'},
  {id:'draw-006',topic:'Conjugated addition',prompt:'Draw the 1,6-addition product from HBr addition to C1=C2–C3=C4–C5=C6 after H adds to C1.',hint:'Br is on C6. The product retains C2=C3 and C4=C5.',answer:'CH₃–CH=CH–CH=CH–CH₂Br',target:G(['C','C','C','C','C','C','Br'],[[0,1,1],[1,2,2],[2,3,1],[3,4,2],[4,5,1],[5,6,1]]),explain:'Extended resonance permits capture at C6. The two remaining π bonds form a conjugated diene.'},
  {id:'draw-007',topic:'Diels–Alder',prompt:'Draw the Diels–Alder product of 1,3-butadiene and ethylene.',hint:'Make a six-membered ring. The inner diene bond becomes the only C=C.',answer:'Cyclohexene',target:G(['C','C','C','C','C','C'],[[0,1,2],[1,2,1],[2,3,1],[3,4,1],[4,5,1],[5,0,1]]),explain:'The diene and dienophile form two new σ bonds in a six-membered ring. One double bond remains between the inner diene carbons.'},
  {id:'draw-008',topic:'Diels–Alder',prompt:'Draw the product skeleton from 1,3-butadiene reacting with acetylene.',hint:'An alkyne dienophile leaves one extra π bond in the ring.',answer:'1,4-cyclohexadiene',target:G(['C','C','C','C','C','C'],[[0,1,2],[1,2,1],[2,3,1],[3,4,2],[4,5,1],[5,0,1]]),explain:'The product retains the shifted diene π bond and one π bond from the alkyne, so it is a cyclohexadiene.'},
  {id:'draw-009',topic:'Dihydroxylation',prompt:'Draw the carbon skeleton and OH bonds of cis-1,2-cyclohexanediol, the OsO₄/NMO product of cyclohexene. Use two wedges or two dashes for the C–O bonds.',hint:'Make a saturated six-membered ring with adjacent O atoms on the same face.',answer:'cis-1,2-cyclohexanediol',targets:[G(['C','C','C','C','C','C','O','O'],[[0,1,1],[1,2,1],[2,3,1],[3,4,1],[4,5,1],[5,0,1],[0,6,1,'wedge'],[1,7,1,'wedge']]),G(['C','C','C','C','C','C','O','O'],[[0,1,1],[1,2,1],[2,3,1],[3,4,1],[4,5,1],[5,0,1],[0,6,1,'dash'],[1,7,1,'dash']])],explain:'Syn addition puts both new C–O bonds on the same face. Terminal O labels imply OH in this neutral line structure.'},
  {id:'draw-010',topic:'Ozonolysis',prompt:'Draw the alkene that gives acetone and propanal after 1. O₃, 2. DMS.',hint:'Remove both carbonyl oxygens and connect the two carbonyl carbons with C=C.',answer:'2-methyl-2-pentene, (CH₃)₂C=CHCH₂CH₃',target:G(['C','C','C','C','C','C'],[[0,1,1],[1,2,1],[1,3,2],[3,4,1],[4,5,1]]),explain:'Acetone supplies a carbonyl carbon bearing two methyl groups; propanal supplies one bearing H and ethyl. Joining those carbons gives 2-methyl-2-pentene.'},
  {id:'draw-011',topic:'Ozonolysis',prompt:'Draw the single product from reductive ozonolysis of cyclohexene.',hint:'Open the ring at C=C and put C=O at both ends.',answer:'OHC–(CH₂)₄–CHO (hexane-1,6-dial)',target:G(['O','C','C','C','C','C','C','O'],[[0,1,2],[1,2,1],[2,3,1],[3,4,1],[4,5,1],[5,6,1],[6,7,2]]),explain:'Cleavage opens the ring but does not split the four intervening methylene groups. Both alkene carbons carried H, so both ends are aldehydes.'},
  {id:'draw-012',topic:'Ozonolysis',prompt:'Draw glyoxal, the two-carbon dialdehyde produced when the middle bond of a conjugated diene survives ozonolysis.',hint:'Two carbonyl carbons connected by one C–C bond; each carbonyl carbon also has H.',answer:'OHC–CHO',target:G(['O','C','C','O'],[[0,1,2],[1,2,1],[2,3,2]]),explain:'Glyoxal is a two-carbon chain with an aldehyde carbonyl at each end.'},
  {id:'draw-013',topic:'Wittig',prompt:'Draw the alkene product of acetone + Ph₃P=CH₂.',hint:'Replace C=O with C=CH₂ while retaining both methyl groups.',answer:'2-methylpropene, (CH₃)₂C=CH₂',target:G(['C','C','C','C'],[[0,1,1],[1,2,1],[1,3,2]]),explain:'The carbonyl carbon retains its two methyl groups and forms a double bond to the ylide methylene carbon.'},
  {id:'draw-014',topic:'Wittig',prompt:'Draw the alkene product of cyclohexanone + Ph₃P=CH₂.',hint:'The new =CH₂ is outside the six-membered ring.',answer:'Methylenecyclohexane',target:G(['C','C','C','C','C','C','C'],[[0,1,1],[1,2,1],[2,3,1],[3,4,1],[4,5,1],[5,0,1],[0,6,2]]),explain:'The ring carbonyl carbon stays in the ring and double-bonds to the ylide carbon, producing an exocyclic methylene.'},
  {id:'draw-015',topic:'Aromaticity',prompt:'Draw one valid Kekulé line structure for benzene.',hint:'Six-membered ring with alternating single and double bonds.',answer:'Benzene, C₆H₆',target:G(['C','C','C','C','C','C'],[[0,1,2],[1,2,1],[2,3,2],[3,4,1],[4,5,2],[5,0,1]]),explain:'A Kekulé contributor has a six-carbon ring with three alternating double bonds. Rotation gives an equivalent drawing.'},
  {id:'draw-016',topic:'EAS',prompt:'Draw bromobenzene, the product of benzene + Br₂/FeBr₃.',hint:'Keep the aromatic ring and replace one ring H with Br.',answer:'C₆H₅Br',target:G(['C','C','C','C','C','C','Br'],[[0,1,2],[1,2,1],[2,3,2],[3,4,1],[4,5,2],[5,0,1],[0,6,1]]),explain:'Electrophilic aromatic substitution replaces one H with Br while restoring the aromatic π system.'}
];
DRAW_BANK.push(
  {id:'draw-017',topic:'Conjugation',prompt:'Draw isolated 1,4-pentadiene.',hint:'Five carbons; the two C=C bonds are separated by two single bonds.',answer:'CH₂=CH–CH₂–CH=CH₂',target:G(['C','C','C','C','C'],[[0,1,2],[1,2,1],[2,3,1],[3,4,2]]),explain:'The central sp³ CH₂ interrupts conjugation, so the double bonds are isolated.'},
  {id:'draw-018',topic:'Conjugation',prompt:'Draw propadiene (allene), the simplest cumulated diene.',hint:'Three carbons with two adjacent double bonds.',answer:'CH₂=C=CH₂',target:G(['C','C','C'],[[0,1,2],[1,2,2]]),explain:'Cumulated dienes have adjacent π bonds, C=C=C, rather than alternating C=C–C=C.'},
  {id:'draw-019',topic:'Conjugated addition',prompt:'Draw the 1,4-addition product from HBr addition to 1,3-butadiene after H adds to C1.',hint:'Place Br at C4 and C=C between C2 and C3.',answer:'CH₃–CH=CH–CH₂Br',target:G(['C','C','C','C','Br'],[[0,1,1],[1,2,2],[2,3,1],[3,4,1]]),explain:'Extended capture at C4 gives the 1,4 product while the inner carbons retain the double bond.'},
  {id:'draw-020',topic:'Conjugated addition',prompt:'Draw the 1,2-addition product from HCl addition to 1,3-butadiene after H adds to C1.',hint:'Place Cl at C2; C3=C4 remains.',answer:'CH₃–CH(Cl)–CH=CH₂',target:G(['C','C','C','C','Cl'],[[0,1,1],[1,2,1],[2,3,2],[1,4,1]]),explain:'Chloride capture at the first cation site gives the 1,2 product.'},
  {id:'draw-021',topic:'Conjugated addition',prompt:'Draw the 1,4-addition product from HCl addition to 1,3-butadiene after H adds to C1.',hint:'Place Cl at C4 and shift the alkene to C2=C3.',answer:'CH₃–CH=CH–CH₂Cl',target:G(['C','C','C','C','Cl'],[[0,1,1],[1,2,2],[2,3,1],[3,4,1]]),explain:'Resonance places positive charge at C4; chloride capture leaves the internal C2=C3 bond.'},
  {id:'draw-022',topic:'Diels–Alder',prompt:'Draw the Diels–Alder product of 1,3-butadiene and propene.',hint:'Make a cyclohexene and keep the propene methyl group on a dienophile-derived saturated carbon.',answer:'A methylcyclohexene',target:G(['C','C','C','C','C','C','C'],[[0,1,2],[1,2,1],[2,3,1],[3,4,1],[4,5,1],[5,0,1],[3,6,1]]),explain:'The six reacting atoms form a cyclohexene; propene contributes one methyl substituent.'},
  {id:'draw-023',topic:'Diels–Alder',prompt:'Draw the product from 1,3-butadiene and cis-2-butene. Use two wedges or two dashes for the methyl bonds.',hint:'The adjacent methyl groups remain cis on the saturated dienophile-derived carbons.',answer:'cis-dimethylcyclohexene',targets:[G(['C','C','C','C','C','C','C','C'],[[0,1,2],[1,2,1],[2,3,1],[3,4,1],[4,5,1],[5,0,1],[3,6,1,'wedge'],[4,7,1,'wedge']]),G(['C','C','C','C','C','C','C','C'],[[0,1,2],[1,2,1],[2,3,1],[3,4,1],[4,5,1],[5,0,1],[3,6,1,'dash'],[4,7,1,'dash']])],explain:'Diels–Alder preserves the cis relationship of substituents on the dienophile.'},
  {id:'draw-024',topic:'Diels–Alder',prompt:'Draw the product from 1,3-butadiene and trans-2-butene. Use one wedge and one dash for the methyl bonds.',hint:'The adjacent methyl groups remain trans.',answer:'trans-dimethylcyclohexene',targets:[G(['C','C','C','C','C','C','C','C'],[[0,1,2],[1,2,1],[2,3,1],[3,4,1],[4,5,1],[5,0,1],[3,6,1,'wedge'],[4,7,1,'dash']]),G(['C','C','C','C','C','C','C','C'],[[0,1,2],[1,2,1],[2,3,1],[3,4,1],[4,5,1],[5,0,1],[3,6,1,'dash'],[4,7,1,'wedge']])],explain:'The trans relationship on the dienophile is retained in the cycloadduct.'},
  {id:'draw-025',topic:'Diels–Alder',prompt:'Draw the product skeleton from isoprene (2-methyl-1,3-butadiene) and ethylene.',hint:'The methyl group stays attached to an alkene carbon in the cyclohexene product.',answer:'A methyl-substituted cyclohexene',target:G(['C','C','C','C','C','C','C'],[[0,1,2],[1,2,1],[2,3,1],[3,4,1],[4,5,1],[5,0,1],[0,6,1]]),explain:'The methyl substituent stays on its original diene carbon, which becomes one carbon of the remaining product alkene.'},
  {id:'draw-026',topic:'Dihydroxylation',prompt:'Draw cis-1,2-cyclopentanediol from cyclopentene + OsO₄/NMO. Use two wedges or two dashes.',hint:'Saturate the five-membered ring alkene and add adjacent OH groups syn.',answer:'cis-1,2-cyclopentanediol',targets:[G(['C','C','C','C','C','O','O'],[[0,1,1],[1,2,1],[2,3,1],[3,4,1],[4,0,1],[0,5,1,'wedge'],[1,6,1,'wedge']]),G(['C','C','C','C','C','O','O'],[[0,1,1],[1,2,1],[2,3,1],[3,4,1],[4,0,1],[0,5,1,'dash'],[1,6,1,'dash']])],explain:'Both C–O bonds form on the same face and the carbon ring remains intact.'},
  {id:'draw-027',topic:'Dihydroxylation',prompt:'Draw the constitutional product from 2-methylpropene + OsO₄/NMO and water.',hint:'Convert C=C to C–C and attach OH to both former alkene carbons.',answer:'2-methylpropane-1,2-diol',target:G(['C','C','C','C','O','O'],[[0,1,1],[1,2,1],[1,3,1],[0,4,1],[1,5,1]]),explain:'The terminal carbon becomes CH₂OH and the substituted carbon becomes C(OH)(CH₃)₂.'},
  {id:'draw-028',topic:'Ozonolysis',prompt:'Draw both carbonyl products from reductive ozonolysis of 2-methylpropene as disconnected structures.',hint:'Terminal =CH₂ gives formaldehyde; the substituted carbon gives acetone. Deselect the current atom before starting the second fragment.',answer:'Acetone + formaldehyde',target:G(['C','C','C','O','C','O'],[[0,1,1],[1,2,1],[1,3,2],[4,5,2]]),explain:'Cleavage yields acetone from the carbon bearing two methyl groups and formaldehyde from terminal CH₂.'},
  {id:'draw-029',topic:'Ozonolysis',prompt:'Draw both products from reductive ozonolysis of 3-methyl-2-pentene as disconnected structures.',hint:'The H-bearing alkene carbon gives ethanal; the carbon bearing methyl and ethyl gives 2-butanone.',answer:'Ethanal + 2-butanone',target:G(['C','C','O','C','C','C','C','O'],[[0,1,1],[1,2,2],[3,4,1],[4,5,1],[5,6,1],[4,7,2]]),explain:'All six carbons are retained across ethanal and 2-butanone.'},
  {id:'draw-030',topic:'Ozonolysis',prompt:'Reconstruct the alkene that gives acetone and formaldehyde under 1. O₃, 2. DMS.',hint:'Remove the carbonyl oxygens and join the two carbonyl carbons with C=C.',answer:'2-methylpropene',target:G(['C','C','C','C'],[[0,1,1],[1,2,1],[1,3,2]]),explain:'Acetone supplies the carbon bearing two methyl groups and formaldehyde supplies terminal CH₂.'},
  {id:'draw-031',topic:'Ozonolysis',prompt:'Draw the single product from reductive ozonolysis of cyclopentene.',hint:'Open the ring at C=C and put an aldehyde at each end.',answer:'OHC–(CH₂)₃–CHO',target:G(['O','C','C','C','C','C','O'],[[0,1,2],[1,2,1],[2,3,1],[3,4,1],[4,5,1],[5,6,2]]),explain:'The five ring carbons become one five-carbon dialdehyde chain.'},
  {id:'draw-032',topic:'Wittig',prompt:'Draw the alkene product from benzaldehyde + Ph₃P=CH₂.',hint:'Replace benzaldehyde C=O with C=CH₂ while keeping the phenyl ring.',answer:'Styrene, C₆H₅CH=CH₂',target:G(['C','C','C','C','C','C','C','C'],[[0,1,2],[1,2,1],[2,3,2],[3,4,1],[4,5,2],[5,0,1],[0,6,1],[6,7,2]]),explain:'The carbonyl carbon remains attached to phenyl and double-bonds to the ylide methylene carbon.'},
  {id:'draw-033',topic:'Wittig',prompt:'Draw the product from cyclopentanone + Ph₃P=CH₂.',hint:'Place an exocyclic =CH₂ on the five-membered ring.',answer:'Methylenecyclopentane',target:G(['C','C','C','C','C','C'],[[0,1,1],[1,2,1],[2,3,1],[3,4,1],[4,0,1],[0,5,2]]),explain:'The ring carbonyl carbon becomes the ring end of an exocyclic C=CH₂ bond.'},
  {id:'draw-034',topic:'Wittig',prompt:'Draw the carbon skeleton produced by ethanal + Ph₃P=CHCH₃.',hint:'Join the carbonyl carbon and ylide carbon with C=C; each retains CH₃ and H.',answer:'2-butene skeleton',target:G(['C','C','C','C'],[[0,1,1],[1,2,2],[2,3,1]]),explain:'The two reacting carbons become the internal alkene carbons of a four-carbon chain.'},
  {id:'draw-035',topic:'Wittig',prompt:'Draw the alkene product from acetone + Ph₃P=CHCH₃.',hint:'The carbonyl carbon retains two methyl groups; the ylide carbon retains H and CH₃.',answer:'2-methyl-2-butene',target:G(['C','C','C','C','C'],[[0,1,1],[1,2,1],[1,3,2],[3,4,1]]),explain:'Joining the acetone carbonyl carbon to the ethylidene ylide carbon gives 2-methyl-2-butene.'},
  {id:'draw-036',topic:'Synthesis',prompt:'Draw the final product of cyclopentanone → 1. Ph₃P=CH₂  2. OsO₄, NMO; H₂O.',hint:'First make methylenecyclopentane, then add OH to both exocyclic alkene carbons.',answer:'1-(Hydroxymethyl)cyclopentan-1-ol',target:G(['C','C','C','C','C','C','O','O'],[[0,1,1],[1,2,1],[2,3,1],[3,4,1],[4,0,1],[0,5,1],[0,6,1],[5,7,1]]),explain:'Wittig adds one carbon outside the ring; syn dihydroxylation gives ring C–OH and CH₂OH.'},
  {id:'draw-037',topic:'Aromaticity',prompt:'Draw one Kekulé structure of pyridine.',hint:'Use a six-membered aromatic ring with one ring atom labeled N and three alternating double bonds.',answer:'Pyridine, C₅H₅N',target:G(['N','C','C','C','C','C'],[[0,1,2],[1,2,1],[2,3,2],[3,4,1],[4,5,2],[5,0,1]]),explain:'Pyridine has a six-membered conjugated ring with one nitrogen replacing CH.'},
  {id:'draw-038',topic:'Aromaticity',prompt:'Draw cyclopentadiene, the neutral nonaromatic five-membered ring.',hint:'Five-membered ring with two C=C bonds separated by one single bond and one sp³ CH₂ carbon.',answer:'Cyclopenta-1,3-diene',target:G(['C','C','C','C','C'],[[0,1,2],[1,2,1],[2,3,2],[3,4,1],[4,0,1]]),explain:'The CH₂ position interrupts continuous cyclic conjugation, making the neutral compound nonaromatic.'},
  {id:'draw-039',topic:'Aromaticity',prompt:'Draw a line structure for cyclooctatetraene.',hint:'Eight-membered ring with four alternating double bonds.',answer:'Cycloocta-1,3,5,7-tetraene',target:G(['C','C','C','C','C','C','C','C'],[[0,1,2],[1,2,1],[2,3,2],[3,4,1],[4,5,2],[5,6,1],[6,7,2],[7,0,1]]),explain:'Cyclooctatetraene has an alternating eight-membered ring but adopts a nonplanar shape and is nonaromatic.'},
  {id:'draw-040',topic:'EAS',prompt:'Draw chlorobenzene, the product of benzene + Cl₂/FeCl₃.',hint:'Replace one benzene H with Cl while retaining the aromatic ring.',answer:'C₆H₅Cl',target:G(['C','C','C','C','C','C','Cl'],[[0,1,2],[1,2,1],[2,3,2],[3,4,1],[4,5,2],[5,0,1],[0,6,1]]),explain:'Electrophilic aromatic substitution installs Cl and restores the benzene π system.'}
);

let drawQuestion=null,drawGraph={nodes:[],edges:[]},drawSelected=null,drawAtom='C',drawOrder=1,drawStereo='',drawMode='draw',drawHistory=[],drawFeedback='';
function pickDrawQuestion(){
  state.drawSeen=state.drawSeen||[];
  const pool=DRAW_BANK.filter(q=>!state.drawSeen.includes(q.id));
  drawQuestion=pool.length?pool[Math.floor(Math.random()*pool.length)]:null;
  if(drawQuestion){state.drawSeen.push(drawQuestion.id);save()}
  drawGraph={nodes:[],edges:[]};drawSelected=null;drawHistory=[];drawFeedback='';
}
function structureLab(){
  state.drawSeen=state.drawSeen||[];
  if(!drawQuestion&&DRAW_BANK.some(q=>!state.drawSeen.includes(q.id)))pickDrawQuestion();
  const left=DRAW_BANK.length-state.drawSeen.length;
  if(!drawQuestion)return heading('Structure Lab','You finished every fresh drawing prompt.',`${DRAW_BANK.length} structures retired without repetition.`)+`<div class="card empty"><h2>Structure bank complete</h2><p class="muted">Your answers stay retired. Review lessons and written practice for more mechanism work.</p></div>`;
  return heading('Structure Lab','Build the molecule, one bond at a time.',`${left} unseen structure questions remain. Connectivity, bond order, atom labels and required wedge/dash bonds are checked automatically.`)+`<div class="structure-shell"><section class="card structure-question"><div class="qhead"><span class="eyebrow">${drawQuestion.topic}</span><span class="tag">${drawQuestion.id}</span></div><div class="qprompt">${drawQuestion.prompt}</div>${reactantScheme(drawQuestion.id)}<details><summary>Hint</summary><p class="muted small">${drawQuestion.hint}</p></details><div id="draw-feedback" aria-live="polite">${drawFeedback}</div></section><section class="card structure-editor"><div class="draw-toolbar" aria-label="Structure drawing tools"><div class="tool-group"><span>Atoms</span>${['C','O','N','Br','Cl'].map(a=>`<button class="draw-tool ${drawMode==='draw'&&drawAtom===a?'active':''}" data-atom="${a}">${a}</button>`).join('')}</div><div class="tool-group"><span>Bonds</span>${[[1,'—'],[2,'═'],[3,'≡']].map(([o,l])=>`<button class="draw-tool ${drawOrder===o&&!drawStereo&&drawMode==='draw'?'active':''}" data-bond="${o}">${l}</button>`).join('')}<button class="draw-tool ${drawStereo==='wedge'?'active':''}" data-stereo="wedge">▲</button><button class="draw-tool ${drawStereo==='dash'?'active':''}" data-stereo="dash">⋮</button></div><div class="tool-group"><span>Edit</span><button class="draw-tool ${drawMode==='erase'?'active':''}" data-mode="erase">Erase</button><button class="draw-tool" id="draw-undo">Undo</button><button class="draw-tool" id="draw-clear">Clear</button></div></div><div class="draw-help">Click empty space to add an atom. Keep clicking to grow a chain. Click one atom and then another to connect them or make a ring. Click the selected atom again before starting a disconnected product. Choose a bond first to change the next connection.</div><svg id="structure-canvas" viewBox="0 0 720 430" role="img" aria-label="Interactive skeletal structure editor"><defs><pattern id="grid" width="30" height="30" patternUnits="userSpaceOnUse"><path d="M30 0H0V30" fill="none" stroke="#edf0f4" stroke-width="1"/></pattern></defs><rect width="720" height="430" fill="url(#grid)"/></svg><div class="structure-actions"><button class="btn" id="draw-answer">Show answer</button><span class="note">Carbon labels are hidden after placement. Terminal O is read as OH unless double-bonded.</span><div class="actions"><button class="btn" id="draw-skip">Skip & retire</button><button class="btn primary" id="draw-check">Check structure</button><button class="btn primary hidden" id="draw-next">Next fresh structure →</button></div></div></section></div>`;
}
function drawSnapshot(){drawHistory.push(JSON.stringify(drawGraph));if(drawHistory.length>40)drawHistory.shift()}
function edgeBetween(a,b,graph=drawGraph){return graph.edges.find(e=>(e.a===a&&e.b===b)||(e.a===b&&e.b===a))}
function addDrawNode(x,y,label){drawSnapshot();const id=drawGraph.nodes.length?Math.max(...drawGraph.nodes.map(n=>n.id))+1:0;drawGraph.nodes.push({id,label,x,y});if(drawSelected!==null)drawGraph.edges.push({id:Date.now()+Math.random(),a:drawSelected,b:id,order:drawOrder,stereo:drawStereo});drawSelected=id;drawMode='draw'}
function removeDrawNode(id){drawSnapshot();drawGraph.nodes=drawGraph.nodes.filter(n=>n.id!==id);drawGraph.edges=drawGraph.edges.filter(e=>e.a!==id&&e.b!==id);if(drawSelected===id)drawSelected=null}
function bondLines(e,a,b){
  const dx=b.x-a.x,dy=b.y-a.y,len=Math.hypot(dx,dy)||1,nx=-dy/len*5,ny=dx/len*5;
  if(e.stereo==='wedge')return `<polygon points="${a.x},${a.y} ${b.x+nx*1.7},${b.y+ny*1.7} ${b.x-nx*1.7},${b.y-ny*1.7}" fill="#303846"/>`;
  if(e.stereo==='dash'){let s='';for(let i=1;i<7;i++){const t=i/7,w=i*.7,x=a.x+dx*t,y=a.y+dy*t;s+=`<line x1="${x-nx*w/5}" y1="${y-ny*w/5}" x2="${x+nx*w/5}" y2="${y+ny*w/5}"/>`}return `<g stroke="#303846" stroke-width="2">${s}</g>`}
  const offsets=e.order===1?[0]:e.order===2?[-1,1]:[-1.5,0,1.5];
  return offsets.map(k=>`<line x1="${a.x+nx*k}" y1="${a.y+ny*k}" x2="${b.x+nx*k}" y2="${b.y+ny*k}" stroke="#303846" stroke-width="3" stroke-linecap="round"/>`).join('')
}
function renderDrawGraph(){
  const svg=document.querySelector('#structure-canvas');if(!svg)return;
  const base='<defs><pattern id="grid" width="30" height="30" patternUnits="userSpaceOnUse"><path d="M30 0H0V30" fill="none" stroke="#edf0f4" stroke-width="1"/></pattern></defs><rect width="720" height="430" fill="url(#grid)"/>';
  const edges=drawGraph.edges.map(e=>{const a=drawGraph.nodes.find(n=>n.id===e.a),b=drawGraph.nodes.find(n=>n.id===e.b);if(!a||!b)return '';return `<g data-edge="${e.id}" class="draw-edge">${bondLines(e,a,b)}<line x1="${a.x}" y1="${a.y}" x2="${b.x}" y2="${b.y}" stroke="transparent" stroke-width="18"/></g>`}).join('');
  const nodes=drawGraph.nodes.map(n=>`<g data-node="${n.id}" class="draw-node ${drawSelected===n.id?'selected':''}"><circle cx="${n.x}" cy="${n.y}" r="16"/><text x="${n.x}" y="${n.y+6}" text-anchor="middle">${n.label==='C'?'•':n.label}</text></g>`).join('');
  svg.innerHTML=base+edges+nodes;
  document.querySelectorAll('[data-atom]').forEach(b=>b.classList.toggle('active',drawMode!=='erase'&&drawAtom===b.dataset.atom));
  document.querySelectorAll('[data-bond]').forEach(b=>b.classList.toggle('active',drawMode==='draw'&&!drawStereo&&drawOrder===Number(b.dataset.bond)));
  document.querySelectorAll('[data-stereo]').forEach(b=>b.classList.toggle('active',drawMode==='draw'&&drawStereo===b.dataset.stereo));
  document.querySelector('[data-mode="erase"]')?.classList.toggle('active',drawMode==='erase');
}
function edgeCompatible(user,target,options={}){return user&&(options.ignoreBond||user.order===target.order)&&(options.ignoreStereo||!target.stereo||user.stereo===target.stereo)}
function graphMatches(user,target,options={}){
  if(user.nodes.length!==target.nodes.length||user.edges.length!==target.edges.length)return false;
  const degree=(g,id)=>g.edges.filter(e=>e.a===id||e.b===id).map(e=>options.ignoreBond?1:e.order).sort().join(',');
  const candidates=user.nodes.map(u=>target.nodes.filter(t=>t.label===u.label&&degree(user,u.id)===degree(target,t.id)).map(t=>t.id));
  if(candidates.some(c=>!c.length))return false;
  const map=new Map(),used=new Set();
  function search(i){
    if(i===user.nodes.length)return true;
    const u=user.nodes[i];
    for(const tid of candidates[i]){if(used.has(tid))continue;let ok=true;for(const [uid,mapped] of map){const ue=edgeBetween(u.id,uid,user),te=edgeBetween(tid,mapped,target);if(Boolean(ue)!==Boolean(te)||(ue&&!edgeCompatible(ue,te,options))){ok=false;break}}if(!ok)continue;map.set(u.id,tid);used.add(tid);if(search(i+1))return true;map.delete(u.id);used.delete(tid)}
    return false;
  }
  return search(0)
}
function graphComponents(g){const left=new Set(g.nodes.map(n=>n.id));let count=0;while(left.size){count++;const stack=[left.values().next().value];left.delete(stack[0]);while(stack.length){const id=stack.pop();for(const e of g.edges.filter(e=>e.a===id||e.b===id)){const other=e.a===id?e.b:e.a;if(left.delete(other))stack.push(other)}}}return count}
function atomTally(g){const out={};for(const n of g.nodes)out[n.label]=(out[n.label]||0)+1;return out}
function diagnoseGraph(user,targets){
  const target=targets[0],u=atomTally(user),t=atomTally(target),labels=[...new Set([...Object.keys(u),...Object.keys(t)])],atomProblems=labels.filter(x=>(u[x]||0)!==(t[x]||0));
  if(atomProblems.length)return `Atom count: your drawing has ${labels.map(x=>`${u[x]||0} ${x}`).join(', ')}; the target requires ${labels.map(x=>`${t[x]||0} ${x}`).join(', ')}.`;
  const uc=graphComponents(user),tc=graphComponents(target);if(uc!==tc)return `Fragment count: you drew ${uc} connected structure${uc===1?'':'s'}, but this answer requires ${tc}. Click the selected atom again before starting a separate product.`;
  if(user.edges.length!==target.edges.length)return `Bond count: your drawing has ${user.edges.length} connections; the target requires ${target.edges.length}. Check for a missing ring closure, branch or extra bond.`;
  if(targets.some(x=>graphMatches(user,x,{ignoreStereo:true})))return 'Connectivity and bond orders are correct. Fix only the required wedge/dash relationship.';
  if(targets.some(x=>graphMatches(user,x,{ignoreBond:true,ignoreStereo:true})))return 'Atom connectivity is correct. Fix one or more single, double or triple bond orders.';
  const over=user.nodes.filter(n=>{const max={C:4,O:2,N:4,Br:1,Cl:1}[n.label]||4;return user.edges.filter(e=>e.a===n.id||e.b===n.id).reduce((s,e)=>s+e.order,0)>max});
  if(over.length)return `Valence problem: ${[...new Set(over.map(n=>n.label))].join(', ')} has too many bonds. Ordinary C cannot exceed four bond-order units; O two; halogens one.`;
  return 'The atom inventory is right, but the connectivity differs. Trace the carbon skeleton first, then attach O, N or halogen labels to the correct carbon.';
}
const drawTopicId=t=>({'Foundations':'basics','Conjugation':'conjugation','Conjugated addition':'conjugation','Diels–Alder':'diels','Dihydroxylation':'diol','Ozonolysis':'ozone','Wittig':'wittig','Synthesis':'synthesis','Aromaticity':'aromatic','EAS':'eas'}[t]||'basics');
function drawResult(){state.drawResults=state.drawResults||[];let r=state.drawResults.find(x=>x.id===drawQuestion.id);if(!r){r={id:drawQuestion.id,topic:drawTopicId(drawQuestion.topic),attempts:0,correct:false,assisted:false,at:Date.now()};state.drawResults.push(r)}return r}
function setDrawFeedback(html){drawFeedback=html;const e=document.querySelector('#draw-feedback');if(e)e.innerHTML=html}
function bindStructureLab(){
  renderDrawGraph();
  document.querySelectorAll('[data-atom]').forEach(b=>b.onclick=()=>{drawAtom=b.dataset.atom;drawMode=drawAtom==='C'?'draw':'atom';renderDrawGraph()});
  document.querySelectorAll('[data-bond]').forEach(b=>b.onclick=()=>{drawMode='draw';drawOrder=Number(b.dataset.bond);drawStereo='';renderDrawGraph()});
  document.querySelectorAll('[data-stereo]').forEach(b=>b.onclick=()=>{drawMode='draw';drawOrder=1;drawStereo=b.dataset.stereo;renderDrawGraph()});
  document.querySelector('[data-mode="erase"]')?.addEventListener('click',()=>{drawMode='erase';renderDrawGraph()});
  document.querySelector('#draw-undo')?.addEventListener('click',()=>{if(drawHistory.length){drawGraph=JSON.parse(drawHistory.pop());drawSelected=null;setDrawFeedback('');renderDrawGraph()}});
  document.querySelector('#draw-clear')?.addEventListener('click',()=>{if(drawGraph.nodes.length){drawSnapshot();drawGraph={nodes:[],edges:[]};drawSelected=null;setDrawFeedback('');renderDrawGraph()}});
  document.querySelector('#structure-canvas')?.addEventListener('click',e=>{
    const nodeEl=e.target.closest('[data-node]'),edgeEl=e.target.closest('[data-edge]');
    if(nodeEl){const id=Number(nodeEl.dataset.node);if(drawMode==='erase'){removeDrawNode(id)}else if(drawMode==='atom'&&drawAtom!=='C'){drawSnapshot();drawGraph.nodes.find(n=>n.id===id).label=drawAtom;drawSelected=id}else if(drawSelected===null){drawSelected=id}else if(drawSelected===id){drawSelected=null}else{const existing=edgeBetween(drawSelected,id);drawSnapshot();if(existing){existing.order=drawOrder;existing.stereo=drawStereo}else drawGraph.edges.push({id:Date.now()+Math.random(),a:drawSelected,b:id,order:drawOrder,stereo:drawStereo});drawSelected=id}setDrawFeedback('');renderDrawGraph();return}
    if(edgeEl&&drawMode==='erase'){drawSnapshot();drawGraph.edges=drawGraph.edges.filter(x=>String(x.id)!==edgeEl.dataset.edge);setDrawFeedback('');renderDrawGraph();return}
    if(edgeEl){const ed=drawGraph.edges.find(x=>String(x.id)===edgeEl.dataset.edge);if(ed){drawSnapshot();ed.order=drawOrder;ed.stereo=drawStereo;setDrawFeedback('');renderDrawGraph()}return}
    if(drawMode==='erase')return;
    const r=e.currentTarget.getBoundingClientRect(),x=Math.round(((e.clientX-r.left)*720/r.width)/30)*30,y=Math.round(((e.clientY-r.top)*430/r.height)/30)*30;
    addDrawNode(Math.max(30,Math.min(690,x)),Math.max(30,Math.min(400,y)),drawAtom);setDrawFeedback('');renderDrawGraph()
  });
  document.querySelector('#draw-check')?.addEventListener('click',()=>{const targets=drawQuestion.targets||[drawQuestion.target],result=drawResult();result.attempts++;const ok=targets.some(t=>graphMatches(drawGraph,t));if(ok){result.correct=true;result.firstTry=result.attempts===1&&!result.assisted;setDrawFeedback(`<div class="draw-result correct"><b>Structure accepted.</b><p>${drawQuestion.explain}</p><div class="formula">${drawQuestion.answer}</div></div>`);document.querySelector('#draw-next')?.classList.remove('hidden');document.querySelector('#draw-check').disabled=true}else setDrawFeedback(`<div class="draw-result wrong"><b>Not quite yet.</b><p>${diagnoseGraph(drawGraph,targets)}</p><p class="note">Your drawing stays in place so you can revise only the part that is wrong.</p></div>`);save()});
  document.querySelector('#draw-answer')?.addEventListener('click',()=>{const result=drawResult();result.assisted=true;save();setDrawFeedback(`<div class="draw-result"><b>Answer:</b><div class="formula">${drawQuestion.answer}</div><p>${drawQuestion.explain}</p></div>`)});
  document.querySelector('#draw-skip')?.addEventListener('click',()=>{drawResult().assisted=true;save();pickDrawQuestion();render()});
  document.querySelector('#draw-next')?.addEventListener('click',()=>{pickDrawQuestion();render()});
}
